  .hero img { width:100%; height:380px; object-fit:cover; display:block; }
  .hero-body { padding:20px 24px 24px; }
  .hero h2 { font-size:26px; line-height:1.4; margin-bottom:10px; }
  .hero h2 a:hover { color:#e63946; }
  .meta { font-size:13px; color:#888; margin-bottom:10px; }
  .hero p { color:#444; font-size:15px; }
